<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Historia · '.$page['title'];$current=(int)$page['version_no']; ?>
<div class="page-head"><div><p class="eyebrow">Historia wersji</p><h1><?=Html::e($page['title'])?></h1></div><a class="button secondary" href="<?=Html::e(Url::to('/pages/'.$page['id']))?>">Wróć</a></div><section class="card"><table><thead><tr><th>Wersja</th><th>Autor</th><th>Data</th><th>Komentarz</th><th>Akcje</th></tr></thead><tbody><?php foreach($versions as $v):?><tr><td>v<?=Html::e($v['version_no'])?></td><td><?=Html::e($v['author_name'])?></td><td><?=Html::e($v['created_at'])?></td><td><?=Html::e($v['change_comment'])?></td><td><div class="actions"><?php if((int)$v['version_no']!==$current):?><a href="<?=Html::e(Url::to('/pages/'.$page['id'].'/diff?from='.$v['version_no'].'&to='.$current))?>">Porównaj z v<?=$current?></a><?php endif;?><?php if($canEdit):?><form method="post" action="<?=Html::e(Url::to('/pages/'.$page['id'].'/restore'))?>"><?=Csrf::field()?><input type="hidden" name="version" value="<?=Html::e($v['version_no'])?>"><button class="link-button">Przywróć</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></section>
